1	{ config, lib, pkgs, ... }:
2	
3	let
4	  # Providers and models for pi (`~/.pi/agent/models.json`). Same endpoint and
5	  # same key as opencode's `modular` provider — api.modular.com is public, so
6	  # only the key is a secret and it is injected at activation below.
7	  #
8	  # pi is NOT opencode's `mcloud`: that one is the internal deployment behind a
9	  # sops-held hostname and serves a different, much smaller model set. Keeping
10	  # the name `mcloud` here would invite exactly the confusion it caused once
11	  # already, so this provider is called `modular`, matching opencode.nix.
12	  piModels = {
13	    providers = {
14	      modular = {
15	        name = "Modular (api.modular.com)";
16	        baseUrl = "https://api.modular.com/v1";
17	        api = "openai-completions";
18	        # apiKey injected at activation; see the jq filter below.
19	        models = [
20	          # `contextWindow` is REQUIRED on every entry. pi defaults it to 128000
21	          # when absent, and api.modular.com advertises no window in
22	          # `/v1/models`, so an omitted value is silently wrong rather than
23	          # unset — a reviewer on a 262k model auto-compacts at 128k and
24	          # finishes a review it only half read.
25	          #
26	          # Every number below is the server's own, from a 400 that named it:
27	          # a deliberately oversized prompt returns "exceeds the configured
28	          # maximum context length of N tokens". Re-probe rather than assume if
29	          # Modular changes a deployment.
30	          {
31	            # No `reasoning`: this model has no thinking support, unlike the four
32	            # below. Omitted rather than set false so the difference is visible.
33	            id = "google/gemma-4-31b-it";
34	            name = "Gemma 4 31B (Modular)";
35	            contextWindow = 262144;
36	          }
